from pathlib import Path
import json
out=Path('deliverables/language-design-2026-09-09/usability-claims.json')
claims=[]
def add(id,kind,text,sources,pages,limits,feature=None,disposition=None,test=None):
 claims.append(dict(id=id,kind=kind,statement=text,source_ids=sources,locators=[{'source_id':s,'pdf_pages':p} for s,p in zip(sources,pages)],confidence='bounded-primary-evidence' if kind=='source_fact' else 'provisional',limitations=limits,feature=feature,disposition=disposition,proposed_test=test,lifecycle='S2',experiment_status='not_reproduced'))
add('UCL01','source_fact','U01 Study 4 analyzes 72 novice participants across six language conditions; Ruby, Python and Quorum outperform Randomo on token accuracy, while Java and Perl do not show a significant advantage over Randomo. Most real-language pairwise differences are not significant.',['U01'],[[26,28,30,31]],['Novice short tasks; token accuracy; language-feature bundles; a non-significant contrast is not equivalence.'])
add('UCL02','recommendation','Adapt familiar declaration forms for a defined audience, while testing semantic interpretation independently of punctuation.',['U01','U10'],[[26,31,34,35],[4,5,6,7]],['Neither paper evaluates TypeScript or finance developers.'],'TypeScript-like surface','adapt','Compare semantically equivalent financial clauses, stratifying by prior TypeScript and functional-language experience.')
add('UCL03','source_fact','U01 intuition surveys had 166 respondents each with some overlap; generic-syntax ratings were inconclusive.',['U01'],[[7,8,13]],['Ratings are not task performance; self-reported experience.'])
add('UCL04','source_fact','U02 Auction correct completion was 7/10 Obsidian versus 2/10 Solidity. The p≈0.015 comparison conditions on claimed completion; the all-participant comparison was p≈0.070.',['U02'],[[36,37]],['20 analyzed Java programmers; one long-tutorial participant excluded; short training and task.'])
add('UCL05','source_fact','In U02 Casino, all four Obsidian participants with compiling completed programs misused disown; none had a fully correct solution. One Solidity participant had a fully correct solution.',['U02'],[[37,38,39]],['Variable remaining task time; difficult task; one compiler-bug case discarded; not a population effect estimate.'])
add('UCL06','recommendation','Defer general unchecked escape hatches; evaluate whether repair attempts discard obligations or assets to silence diagnostics.',['U02'],[[37,38,39]],['Moriarty is not Obsidian; scoped language semantics require separate design justification.'],'ownership and obligation escape hatches','defer','Observe seeded residual-duty and asset-loss repairs, including requests for unchecked casts or suppressed checks.')
add('UCL07','source_fact','U04 retained 27 of 33 recruited students. Static typing favored three API tasks and dynamic typing two; the task-specific analysis does not establish a universal type-system winner.',['U04'],[[8,9,10,11,14]],['Java-familiar students; carryover; exclusions; stripped-static Groovy API; no mainstream IDE feature comparison.'])
add('UCL08','recommendation','Adapt explicit type information at public financial boundaries and study inferred locals separately from erasing types.',['U04'],[[4,8,13,14]],['Annotations and checking are confounded in this study; inference was future work.'],'local inference and visible signatures','adapt','Equal-signature explicit-local versus inferred-local condition with type display; measure navigation, mistakes and repair time.')
add('UCL09','source_fact','U05 message quizzes had 27 complete cases: incorrect interpretation was 17.28% for standard messages and 6.17% for enhanced messages, with reported paired-test p<0.035.',['U05'],[[6,7,8]],['Message comprehension outside programming context; does not estimate secure repair.'])
add('UCL10','source_fact','U05 think-aloud programming study did not show a substantial overall learning-outcome improvement, despite observations of useful reading and edits in response to enhanced messages.',['U05'],[[7,8,9,10]],['31 sessions; historical semester comparison; compiler access, prior-code access and teacher differences.'])
add('UCL11','recommendation','Adopt separate measures of diagnostic comprehension, correct repair, recurrence and suppression attempts.',['U05','U02'],[[6,7,8,9,10],[37,38]],['Friendly wording alone is not a demonstrated productivity intervention.'],'structured diagnostics','adopt','Seed wrong-asset, recipient, fee and rounding errors; measure first edit and eventual correct obligation-preserving repair.')
add('UCL12','source_fact','U06 Table 4 reports DSL/GPL success means of 57.62/40.95 learning, 64.57/50.86 perceiving, 70.95/33.33 evolving, and 64.34/43.37 overall, in percent.',['U06'],[[24]],['35 retained students; GUI questionnaire comparison, not production coding.'])
add('UCL13','contradiction','U06 conclusion summarizes roughly 15% improvement across categories; Table 4 instead gives 16.67, 13.71 and 37.62 percentage-point differences, and 20.97 overall. Use explicit table numbers.',['U06'],[[24,28]],['No raw-data reanalysis; publisher discrepancy preserved.'])
add('UCL14','inference','U06 inferential statistics require caution: its prose calls the test independent although participants answered both questionnaires; cognitive-dimension attribution assumes equal contribution among selected dimensions.',['U06'],[[22,25,26]],['This is a methodological limitation identified from the paper, not a reanalysis or disproof of its directional observation.'])
add('UCL15','recommendation','Adapt domain-specific financial vocabulary, but defer importing the GUI study effect size into finance.',['U06'],[[20,21,22,24,28]],['One domain and two specific notations; prior familiarity uneven.'],'financial blocks versus library calls','adapt','Compare equivalent partial-payment and rounding-policy edits; include duty survival and wrong-recipient detection.')
add('UCL16','source_fact','U09 pilot uses 18 respondents: ten unsupervised and eight interviewed. Respondents identify concrete usability issues, but group, questionnaire and interview differences prevent a clean causal comparison.',['U09'],[[7,8,9,10]],['Small convenience pilot, no validated scalar language ranking.'])
add('UCL17','recommendation','Adopt cognitive-dimension prompts for visibility, dependencies, change effort and role clarity; defer a summed score ranking entire languages.',['U09'],[[4,5,7,9,10]],['Usability concerns notation plus environment.'],'source editor and dependency presentation','adopt','Ask reviewers to locate all clauses affected by an asset-unit, rounding-policy or residual-duty change.')
add('UCL18','source_fact','U10 reports eight student designers and six completed projects; spontaneous syntax choices and actual task failures reveal prior-experience effects and mistaken designer assumptions.',['U10'],[[2,3,4,5,6,7]],['Qualitative convenience studies; end-user counts not consistently specified; no final-language performance trial.'])
add('UCL19','recommendation','Adapt natural-programming tasks as formative evidence, followed by trained tasks on the actual constrained semantics.',['U10','U02'],[[4,5,6,7],[39,43,44,45,46]],['Spontaneously invented syntax is not proof of learnability or safety.'],'language design process','adapt','Elicit an asset-bound limit, partial repayment and delayed claim before teaching spelling; then test interpretation and repair.')
add('UCL20','open_question','Do content-addressed definitions and explicit dependency identity improve financial-language maintenance compared with name/version-oriented modules?',['U09'],[[9,10]],['None of these seven works directly evaluates Unison or content addressing.'],'Unison-like identity','defer','Compare rename and dependency-update tasks with equivalent semantic checks; track mistaken assumptions about what changed.')
add('UCL21','contradiction','U02 describes both Glacier programming-task contrasts as significant, but one reported p≈0.077 exceeds the conventional 0.05 threshold; retain counts and precise p-values.',['U02'],[[19]],['No reanalysis; do not call this contrast significant at 0.05.'])
add('UCL22','inference','Positive bounded-task results and negative open-ended outcomes can coexist; language evaluations should preserve correctness, completion and time as distinct outcomes.',['U02','U04','U05'],[[36,37,38,39],[8,9,10,11],[8,9,10]],['Heterogeneous tasks and populations; no pooled effect estimate warranted.'])
out.write_text(json.dumps({'schema':'moriarty.language-design.claims.v1','scope':'Empirical language usability; no language implementation or acceptance','canonical_wiki_merged':False,'sources_inventory':'raw/sources/language-design-2026-09-09/usability/source-inventory.json','claims':claims},ensure_ascii=False,indent=2)+'\n')
